function autoWaveTick(){if(!autoWaveOn()||!autoArmed||game.status!=='playing'){autoAt=null;return}const idle=!game.spawnQueue.length&&!game.enemies.some(e=>e.alive)&&game.wave===game.completed&&game.towers.length>0&&!!game.waveAt(game.wave);if(!idle){autoAt=null;return}if(autoAt===null)autoAt=game.time+AUTO_DELAY;if(game.time>=autoAt){autoAt=null;const r=game.startWave();if(!r.ok)feedback(r.reason);events();save()}}
function setAutoWave(on){settings.autoWave=!!on;store('warden.settings.v1',settings);autoAt=null;if(on&&game.wave>game.completed)autoArmed=true;const cb=$('autoWave');if(cb)cb.checked=!!on;feedback(on?(autoArmed?'Auto waves on: the next wave starts 3 seconds after each clear.':'Auto waves on: start the first wave with N, then they keep coming.'):'Auto waves off: start each wave with N.');refresh()}
