function showEngineHint(){if(!ENGINE_RUN||settings.engineHintSeen||!$('engineHint'))return;settings.engineHintSeen=true;store('warden.settings.v1',settings);const h=$('engineHint'),els=['dockTowerList','skillsButton','towerListButton','autoWaveWrap'].map($).filter(Boolean);h.hidden=false;els.forEach(e=>e.classList.add('new-pulse'));const done=()=>{h.hidden=true;els.forEach(e=>e.classList.remove('new-pulse'))};$('engineHintClose').onclick=done;els.forEach(e=>e.addEventListener('click',done,{once:true}));setTimeout(done,20000)}
