function nextWave(){unlockAudio();guide.sync(game);const alive=game.enemies.some(e=>e.alive);/* Oct 24 2026: no confirmation; pressing Next wave while enemies remain sends it right away. */if(alive&&!game.spawnQueue.length){const r=game.startWave(true);if(!r.ok)feedback(r.reason);events();refresh();save()}else{const result=game.startWave();if(!result.ok)feedback(result.reason);events();refresh();save()}}
