 if(t.type==='water'&&t.tier>1&&art.tiers){const frame=WardenTowerLayout.waterFrame(t.tier,t.spec,x,y,width,art.tiers.width,art.tiers.height);crop(c,art.tiers,frame.source,...frame.destination)}
 else if(t.tier>1&&art.elementTiers){const row={fire:0,ice:1,lightning:2}[t.type],col=t.tier===2?0:t.spec===0?1:2,sw=art.elementTiers.width/3,sh=art.elementTiers.height/3;crop(c,art.elementTiers,[col*sw,row*sh,sw,sh],layout.x,layout.y,width,layout.height)}
