function mapPoint(e){const r=canvas.getBoundingClientRect();return G.unproject(((e.clientX-r.left)/r.width*1000-VIEW.x)/VIEW.scale,((e.clientY-r.top)/r.height*600-VIEW.y)/VIEW.scale)}
canvas.addEventListener('pointermove',e=>{hover=mapPoint(e)});canvas.addEventListener('pointerleave',()=>hover=null);
canvas.addEventListener('click',e=>{if(!ready||modalPaused)return;const p=mapPoint(e);if(buildType){buildAt(p);hover=p;return}const screen=G.project(p.x,p.y);const byFront=[...game.towers].sort((a,b)=>G.project(b.x,b.y).y-G.project(a.x,a.y).y);const onBase=byFront.find(t=>{const pos=G.project(t.x,t.y);return Math.abs(pos.x-screen.x)<E.TOWER_BASE.w/2&&Math.abs(pos.y-screen.y)<E.TOWER_BASE.d/2+2});const picked=onBase||byFront.find(t=>{const pos=G.project(t.x,t.y);return Math.abs(pos.x-screen.x)<42&&screen.y>=pos.y-80&&screen.y<=pos.y+26});if(picked){selected=picked.id;guide.record('inspect');buildType=null;enemySelected=null;refresh();return}const enemy=game.enemies.find(v=>game.exposed(v)&&Math.hypot(G.project(v.x,v.y).x-screen.x,G.project(v.x,v.y).y-20-screen.y)<33);selected=null;enemySelected=enemy?.id||null;refresh()});
