// Upgrade hotkey (Oct 22 2026): one choice (Tier I -> II) upgrades at once; two Tier III paths are highlighted,
// arrow keys pick, Enter confirms, Esc cancels. Clicking the buttons works as before.
let specPick=null;
function upgradeHotkey(){const t=game.towers.find(t=>t.id===selected);if(!t){feedback('Select a tower to upgrade it.');return}guide.record('upgradeView');
 if(t.tier===1){upgrade();return}
 if(t.tier===2){const cost=game.upgradeCost(t);if(game.charge<cost){feedback(`Tier III needs ${cost} Charge (you have ${Math.floor(game.charge)}).`);return}
  if(specPick?.id===t.id){upgrade(specPick.i);specPick=null;return}
  specPick={id:t.id,i:0};feedback(`Choose a Tier III path: ← → to pick, Enter (or ${keys.upgrade.toUpperCase()}) to confirm, Esc to cancel.`);markSpecPick();return}
 if(game.endless){overchargeSelected();return}feedback('This tower is already Tier III.')}
function overchargeSelected(){const t=game.towers.find(t=>t.id===selected);if(!t)return;const r=game.overcharge(t.id);feedback(r.ok?`Overcharged to level ${r.level}: +${r.level*15}% damage.`:r.reason);events();refresh();save()}
function markSpecPick(){const t=game.towers.find(t=>t.id===selected);if(specPick&&(!t||t.id!==specPick.id||t.tier!==2))specPick=null;$('selection').querySelectorAll('[data-spec]').forEach((b,i)=>{const on=!!specPick&&specPick.i===i;b.classList.toggle('spec-pick',on);b.setAttribute('aria-pressed',String(on));if(on&&document.activeElement!==b)b.focus?.()})}
function hotkeyAction(action){if(['fire','water','ice','lightning'].includes(action))setType(action);if(action==='pause')togglePause();if(action==='next')nextWave();if(action==='sell')sell();if(action==='target')cycleTarget();if(action==='upgrade')upgradeHotkey();if(['normal','double','fast'].includes(action)){speed={normal:1,double:2,fast:5}[action];refresh()}}
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(modalPaused)return;if(!TUT&&(e.key==='k'||e.key==='K')){e.preventDefault();openBattleSkills();return}if(ENGINE_RUN&&(e.key==='l'||e.key==='L')&&!Object.values(keys).includes('l')){e.preventDefault();toggleTowerList();return}if(ENGINE_RUN&&(e.key==='a'||e.key==='A')&&!Object.values(keys).includes(e.key.toLowerCase())){e.preventDefault();setAutoWave(!settings.autoWave);return}if(specPick){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();specPick.i=specPick.i?0:1;markSpecPick();return}if(e.key==='Enter'){e.preventDefault();const i=specPick.i;specPick=null;upgrade(i);return}if(e.key==='Escape'){e.preventDefault();specPick=null;markSpecPick();feedback('Tier III choice canceled.');return}}if(e.key==='Escape'){if(teach()){settings.guide=false;store('warden.settings.v1',settings);refresh();return}spotlightStep=null;buildType=null;selected=null;enemySelected=null;refresh();return}const action=Object.keys(keys).find(a=>keys[a].toLowerCase()===e.key.toLowerCase());if(action){e.preventDefault();unlockAudio();hotkeyAction(action)}});
function settingsUI(){const list=$('audioControls');list.innerHTML='';for(const [key,label]of[['master','Master'],['effects','Sound FX'],['music','Background music'],['ambience','Ambience']]){const row=document.createElement('label');row.className='audio-row';row.innerHTML=`<span>${label}</span><input aria-label="${label} volume" type="range" min="0" max="1" step="0.05" value="${settings[key]}"><label><input aria-label="Mute ${label}" type="checkbox" ${settings[key+'Mute']?'checked':''}>Mute</label>`;row.querySelector('[type=range]').oninput=e=>{settings[key]=+e.target.value;store('warden.settings.v1',settings);syncAudio()};row.querySelector('[type=checkbox]').onchange=e=>{settings[key+'Mute']=e.target.checked;store('warden.settings.v1',settings);syncAudio()};list.append(row)}$('reduced').checked=settings.reduced;$('guide').checked=settings.guide;$('keybinds').innerHTML='';for(const action of Object.keys(keys)){const label=document.createElement('label');label.textContent=action;label.htmlFor='key-'+action;const input=document.createElement('input');input.id='key-'+action;input.value=keys[action]===' '?'Space':keys[action];input.setAttribute('aria-label',action+' hotkey');input.onkeydown=e=>{e.preventDefault();if(e.ctrlKey||e.altKey||e.metaKey||e.key==='Escape'||e.key.length>1&&e.key!==' ')return;const value=e.key.toLowerCase();if(Object.entries(keys).some(([a,k])=>a!==action&&k===value)){feedback('That hotkey is already assigned.');return}keys[action]=value;input.value=value===' '?'Space':value;store('warden.keys.v1',keys)};$('keybinds').append(label,input)}}
$ ('helpButton').onclick=()=>{refresh();openModal('help')};if($('helpOpenGuide'))$('helpOpenGuide').onclick=()=>{$('help').close();globalThis.WardenGuide?.open(null,openModal)};$('settingsButton').onclick=()=>{settingsUI();openModal('settings')};$('resetKeys').onclick=()=>{keys={...DEFAULT_KEYS};store('warden.keys.v1',keys);settingsUI()};$('reduced').onchange=e=>{settings.reduced=e.target.checked;store('warden.settings.v1',settings)};$('guide').onchange=e=>{settings.guide=e.target.checked;store('warden.settings.v1',settings);refresh()};$('guideToggle').onclick=()=>{settings.guide=false;spotlightStep=null;store('warden.settings.v1',settings);refresh()};
function badgeImg(id,size,cls=''){return `<img class="badge-art ${cls}" src="${WardenBadges.image(id,size)}" alt="" width="${size>128?96:size}" height="${size>128?96:size}" loading="lazy" decoding="async">`}
function showBadges(){const count=Object.keys(game.profile.earned).filter(id=>E.ACHIEVEMENTS.some(a=>a[0]===id)).length;$('profileSummary').textContent=`${count} / ${WardenBadges.publicTotal(E.ACHIEVEMENTS)} earned · ${wfmt(game.profile.parts)} Restoration Parts · local browser profile`;$('achievementList').innerHTML=WardenBadges.listed(E.ACHIEVEMENTS,game.profile).map(([id,name,desc])=>{const earned=game.profile.earned[id],tier=WardenBadges.tier(id),prog=WardenBadges.progress(id,game.profile),equipped=game.profile.equipped===id;const status=earned?'Earned '+new Date(earned).toLocaleDateString():WardenBadges.available(id)?(prog?`${prog.value} / ${prog.goal}`:'Available in the tutorial'):'Requires later maps / endless';return`<article class="achievement ${earned?'earned':'locked'} tier-${tier}"><div class="badge-slot">${badgeImg(id,256,earned?'':'is-locked')}${earned?'':'<span class="badge-lock" aria-hidden="true">🔒</span>'}</div><div class="badge-text"><strong>${name}</strong><span class="badge-tier">${WardenBadges.TIER_LABEL[tier]}${earned?' · Earned':' · Locked'}</span><p>${desc}</p>${prog&&!earned?`<div class="badge-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${prog.goal}" aria-valuenow="${prog.value}"><i style="width:${prog.value/prog.goal*100}%"></i></div>`:''}<small>${status}</small>${earned?`<button class="badge-equip" data-equip="${id}" ${equipped?'aria-pressed="true"':''}>${equipped?'Shown on your profile':'Show on profile'}</button>`:''}</div></article>`}).join('');document.querySelectorAll?.('[data-equip]').forEach(b=>b.onclick=()=>{if(WardenBadges.equip(game.profile,b.dataset.equip)){store('warden.profile.v1',game.profile);refreshProfileBadge();showBadges()}});openModal('badges')}
function refreshProfileBadge(){const b=$('profileButton'),id=game.profile.equipped;if(!b)return;if(id&&game.profile.earned[id]){b.innerHTML=badgeImg(id,128,'profile-badge');b.classList.toggle('has-badge',true);b.title='Badges · showing '+(E.ACHIEVEMENTS.find(a=>a[0]===id)?.[1]||'')}else{b.textContent='◉';b.classList.toggle('has-badge',false);b.title='Achievements'}}
$('profileButton').onclick=showBadges;const goHub=()=>{save();location.href='hub.html'};const hubOpen=()=>!TUT||!!game.profile.seals?.tutorial?.cleared;if($('toHub'))$('toHub').onclick=goHub;if($('hubButton')){$('hubButton').onclick=goHub;$('hubButton').hidden=!hubOpen()}$('resultBadges').onclick=showBadges;$('tierReview').onclick=()=>openModal('tiers');
document.addEventListener('visibilitychange',()=>{if(document.hidden){paused=true;accumulator=0;save();syncAudio();refresh()}});window.addEventListener('pagehide',save);
function frame(now){if(window.WardenAds)WardenAds.gameplay(ready&&!paused&&!modalPaused&&game.status==='playing'&&!document.hidden);const dt=last?Math.min((now-last)/1000,.20):0;last=now;realTime+=dt;if(ready&&!paused&&!modalPaused&&game.status==='playing'){accumulator+=dt*speed*(coach()?.timeScale?.()??1);let steps=0;while(accumulator>=1/60&&steps<65){game.step(1/60);events();autoWaveTick();accumulator-=1/60;steps++;if(game.status!=='playing'){accumulator=0;break}}}else accumulator=0;draw();updateTeaching();coach()?.frame?.(dt);uiTimer+=dt;if(uiTimer>.22){refresh();uiTimer=0}if(realTime-lastSave>2){save();lastSave=realTime}requestAnimationFrame(frame)}
if(!TUT){document.body.classList.add('mission-outer');const h=document.querySelector('.sector-plaque h1'),c=document.querySelector('.sector-plaque .sector-caption');if(h)h.textContent=game.map.name;if($('waveLabel'))$('waveLabel').textContent='WAVE';if(h&&ENGINE_RUN)h.textContent='Engine Trials';if(c)c.textContent=ENGINE_RUN?((game.start?`CHECKPOINT WAVE ${game.start} · `:'')+(Number.isFinite(game.limit)?`AETHERHEART ENGINE · LIMIT WAVE ${game.limit}`:'AETHERHEART ENGINE · UNBOUND')):CAMPAIGN?(game.campaign.finale?'THE FINALE':`${E.CAMP.SECTORS[game.campaign.sector].name.toUpperCase()} · MISSION ${game.campaign.index} OF 3`):`HOLD THE GATE · LEVEL ${game.level}`;document.title=ENGINE_RUN?'Warden of Power · Engine Trials':CAMPAIGN?`Warden of Power · ${game.map.name}`:`Warden of Power · Outer Seal · Level ${game.level}`}
initializeButtons();refreshProfileBadge();refresh();Promise.all(loads).then(()=>{makeTerrain();ready=true;window.WardenAds&&WardenAds.loadingStop();$('loading').hidden=true;events();refresh();requestAnimationFrame(frame)}).catch(error=>{$('loading').textContent='Could not load '+error.message+'. Keep the project folders together and reload.'});
// Tablet / small-window fit (Oct 24 2026): see style.css #gameStage.fit-scale.
(function fitStage(){const st=document.getElementById('gameStage');if(!st||!st.classList||typeof window==='undefined')return;const DW=1280,DH=768;
 const fit=()=>{const vw=window.innerWidth,vh=window.innerHeight,w=Math.min(vw,vh*5/3);if(w<DW-.5){st.classList.add('fit-scale');st.style.setProperty('--fit',Math.min(vw/DW,vh/DH).toFixed(4))}else{st.classList.remove('fit-scale');st.style.removeProperty('--fit')}};
 if(typeof addEventListener==='function'){addEventListener('resize',fit);addEventListener('orientationchange',()=>setTimeout(fit,200))}try{fit()}catch(e){}})();

try{addEventListener('pagehide',()=>window.WardenAds&&WardenAds.gameplay(false))}catch(e){}
